(function() {
    'use strict';
    window.PTPToast = {
        container: null,
        queue: [],
        init: function() {
            if (!this.container) {
                this.container = document.createElement('div');
                this.container.className = 'ptp-toast-container';
                document.body.appendChild(this.container);
            }
        },
        show: function(message, type, duration) {
            this.init();
            type = type || 'info';
            duration = duration || 3500;
            var toast = document.createElement('div');
            toast.className = 'ptp-toast ' + type;
            var icons = {
                success: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><path d="M20 6L9 17l-5-5"/></svg>',
                error: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><path d="M18 6L6 18M6 6l12 12"/></svg>',
                warning: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><path d="M12 9v4m0 4h.01"/></svg>',
                info: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><circle cx="12" cy="12" r="10"/><path d="M12 16v-4m0-4h.01"/></svg>'
            };
            toast.innerHTML =
                '<span class="ptp-toast-icon">' + (icons[type] || icons.info) + '</span>' +
                '<span class="ptp-toast-message">' + message + '</span>' +
                '<button class="ptp-toast-close"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M18 6L6 18M6 6l12 12"/></svg></button>';
            this.container.appendChild(toast);
            var closeBtn = toast.querySelector('.ptp-toast-close');
            closeBtn.addEventListener('click', function() {
                PTPToast.dismiss(toast);
            });
            if (duration > 0) {
                setTimeout(function() {
                    PTPToast.dismiss(toast);
                }, duration);
            }
            return toast;
        },
        dismiss: function(toast) {
            if (!toast || toast.classList.contains('removing')) return;
            toast.classList.add('removing');
            setTimeout(function() {
                if (toast.parentNode) {
                    toast.parentNode.removeChild(toast);
                }
            }, 250);
        },
        success: function(message, duration) {
            return this.show(message, 'success', duration);
        },
        error: function(message, duration) {
            return this.show(message, 'error', duration);
        },
        warning: function(message, duration) {
            return this.show(message, 'warning', duration);
        },
        info: function(message, duration) {
            return this.show(message, 'info', duration);
        }
    };
    window.PTPModal = {
        current: null,
        open: function(modalId) {
            var overlay = document.getElementById(modalId);
            if (!overlay) return;
            overlay.classList.add('open');
            document.body.style.overflow = 'hidden';
            this.current = overlay;
            var focusable = overlay.querySelectorAll('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])');
            if (focusable.length) {
                focusable[0].focus();
            }
            document.addEventListener('keydown', this.handleEsc);
        },
        close: function(modalId) {
            var overlay = modalId ? document.getElementById(modalId) : this.current;
            if (!overlay) return;
            overlay.classList.remove('open');
            document.body.style.overflow = '';
            this.current = null;
            document.removeEventListener('keydown', this.handleEsc);
        },
        handleEsc: function(e) {
            if (e.key === 'Escape' && PTPModal.current) {
                PTPModal.close();
            }
        },
        init: function() {
            document.querySelectorAll('.ptp-modal-overlay').forEach(function(overlay) {
                overlay.addEventListener('click', function(e) {
                    if (e.target === overlay) {
                        PTPModal.close(overlay.id);
                    }
                });
            });
            document.querySelectorAll('[data-modal-close]').forEach(function(btn) {
                btn.addEventListener('click', function() {
                    PTPModal.close();
                });
            });
            document.querySelectorAll('[data-modal-open]').forEach(function(btn) {
                btn.addEventListener('click', function() {
                    var modalId = this.getAttribute('data-modal-open');
                    PTPModal.open(modalId);
                });
            });
        }
    };
    window.PTPBottomSheet = {
        current: null,
        startY: 0,
        currentY: 0,
        open: function(sheetId) {
            var overlay = document.getElementById(sheetId);
            if (!overlay) return;
            overlay.classList.add('open');
            document.body.style.overflow = 'hidden';
            this.current = overlay;
            var sheet = overlay.querySelector('.ptp-bottom-sheet');
            if (sheet) {
                sheet.addEventListener('touchstart', this.handleTouchStart.bind(this));
                sheet.addEventListener('touchmove', this.handleTouchMove.bind(this));
                sheet.addEventListener('touchend', this.handleTouchEnd.bind(this));
            }
        },
        close: function(sheetId) {
            var overlay = sheetId ? document.getElementById(sheetId) : this.current;
            if (!overlay) return;
            overlay.classList.remove('open');
            document.body.style.overflow = '';
            this.current = null;
        },
        handleTouchStart: function(e) {
            this.startY = e.touches[0].clientY;
        },
        handleTouchMove: function(e) {
            this.currentY = e.touches[0].clientY;
            var diff = this.currentY - this.startY;
            if (diff > 0) {
                var sheet = this.current.querySelector('.ptp-bottom-sheet');
                sheet.style.transform = 'translateY(' + diff + 'px)';
            }
        },
        handleTouchEnd: function(e) {
            var diff = this.currentY - this.startY;
            var sheet = this.current.querySelector('.ptp-bottom-sheet');
            if (diff > 100) {
                this.close();
            }
            sheet.style.transform = '';
        },
        init: function() {
            document.querySelectorAll('.ptp-bottom-sheet-overlay').forEach(function(overlay) {
                overlay.addEventListener('click', function(e) {
                    if (e.target === overlay) {
                        PTPBottomSheet.close(overlay.id);
                    }
                });
            });
            document.querySelectorAll('[data-sheet-open]').forEach(function(btn) {
                btn.addEventListener('click', function() {
                    var sheetId = this.getAttribute('data-sheet-open');
                    PTPBottomSheet.open(sheetId);
                });
            });
            document.querySelectorAll('[data-sheet-close]').forEach(function(btn) {
                btn.addEventListener('click', function() {
                    PTPBottomSheet.close();
                });
            });
        }
    };
    window.PTPTabs = {
        init: function() {
            document.querySelectorAll('.ptp-tabs').forEach(function(tabsContainer) {
                var tabs = tabsContainer.querySelectorAll('.ptp-tab');
                var contentId = tabsContainer.getAttribute('data-tabs-for');
                tabs.forEach(function(tab) {
                    tab.addEventListener('click', function() {
                        tabs.forEach(function(t) { t.classList.remove('active'); });
                        tab.classList.add('active');
                        var targetId = tab.getAttribute('data-tab');
                        if (contentId) {
                            var container = document.getElementById(contentId);
                            if (container) {
                                container.querySelectorAll('.ptp-tab-content').forEach(function(content) {
                                    content.classList.remove('active');
                                });
                                var targetContent = container.querySelector('[data-tab-content="' + targetId + '"]');
                                if (targetContent) {
                                    targetContent.classList.add('active');
                                }
                            }
                        }
                    });
                });
            });
        }
    };
    window.PTPDropdown = {
        init: function() {
            document.querySelectorAll('.ptp-dropdown').forEach(function(dropdown) {
                var trigger = dropdown.querySelector('[data-dropdown-trigger]');
                if (!trigger) return;
                trigger.addEventListener('click', function(e) {
                    e.stopPropagation();
                    document.querySelectorAll('.ptp-dropdown.open').forEach(function(d) {
                        if (d !== dropdown) d.classList.remove('open');
                    });
                    dropdown.classList.toggle('open');
                });
            });
            document.addEventListener('click', function() {
                document.querySelectorAll('.ptp-dropdown.open').forEach(function(d) {
                    d.classList.remove('open');
                });
            });
        }
    };
    window.PTPCopy = {
        exec: function(text, successMsg) {
            successMsg = successMsg || 'Copied!';
            if (navigator.clipboard) {
                navigator.clipboard.writeText(text).then(function() {
                    PTPToast.success(successMsg);
                }).catch(function() {
                    PTPCopy.fallback(text, successMsg);
                });
            } else {
                PTPCopy.fallback(text, successMsg);
            }
        },
        fallback: function(text, successMsg) {
            var textarea = document.createElement('textarea');
            textarea.value = text;
            textarea.style.position = 'fixed';
            textarea.style.opacity = '0';
            document.body.appendChild(textarea);
            textarea.select();
            try {
                document.execCommand('copy');
                PTPToast.success(successMsg);
            } catch (err) {
                PTPToast.error('Copy failed');
            }
            document.body.removeChild(textarea);
        },
        init: function() {
            document.querySelectorAll('[data-copy]').forEach(function(el) {
                el.addEventListener('click', function() {
                    var text = this.getAttribute('data-copy');
                    var msg = this.getAttribute('data-copy-msg');
                    PTPCopy.exec(text, msg);
                });
            });
            document.querySelectorAll('[data-copy-input]').forEach(function(btn) {
                btn.addEventListener('click', function() {
                    var inputId = this.getAttribute('data-copy-input');
                    var input = document.getElementById(inputId);
                    if (input) {
                        PTPCopy.exec(input.value);
                    }
                });
            });
        }
    };
    window.PTPScroll = {
        to: function(target, offset) {
            offset = offset || 80;
            var element = typeof target === 'string' ? document.querySelector(target) : target;
            if (element) {
                var top = element.getBoundingClientRect().top + window.pageYOffset - offset;
                window.scrollTo({ top: top, behavior: 'smooth' });
            }
        },
        init: function() {
            document.querySelectorAll('a[href^="#"]').forEach(function(anchor) {
                anchor.addEventListener('click', function(e) {
                    var href = this.getAttribute('href');
                    if (href.length > 1) {
                        e.preventDefault();
                        PTPScroll.to(href);
                    }
                });
            });
        }
    };
    window.PTPLoading = {
        show: function(container) {
            container = typeof container === 'string' ? document.querySelector(container) : container;
            if (!container) return;
            container.style.position = 'relative';
            var overlay = document.createElement('div');
            overlay.className = 'ptp-loading-overlay';
            overlay.innerHTML = '<div class="ptp-spinner ptp-spinner-lg"></div>';
            container.appendChild(overlay);
        },
        hide: function(container) {
            container = typeof container === 'string' ? document.querySelector(container) : container;
            if (!container) return;
            var overlay = container.querySelector('.ptp-loading-overlay');
            if (overlay) {
                overlay.remove();
            }
        },
        button: function(btn, loading) {
            btn = typeof btn === 'string' ? document.querySelector(btn) : btn;
            if (!btn) return;
            if (loading) {
                btn.disabled = true;
                btn.dataset.originalText = btn.innerHTML;
                btn.innerHTML = '<span class="ptp-spinner ptp-spinner-sm"></span>';
            } else {
                btn.disabled = false;
                if (btn.dataset.originalText) {
                    btn.innerHTML = btn.dataset.originalText;
                }
            }
        }
    };
    window.PTPFavorite = {
        toggle: function(btn, trainerId) {
            btn.classList.toggle('active');
            var isActive = btn.classList.contains('active');
            if (typeof jQuery !== 'undefined' && typeof ptp_ajax !== 'undefined') {
                jQuery.ajax({
                    url: ptp_ajax.ajax_url,
                    type: 'POST',
                    data: {
                        action: 'ptp_toggle_favorite',
                        trainer_id: trainerId,
                        favorite: isActive ? 1 : 0,
                        nonce: ptp_ajax.nonce
                    }
                });
            }
            PTPToast.success(isActive ? 'Added to favorites!' : 'Removed from favorites');
        },
        init: function() {
            document.querySelectorAll('.ptp-trainer-card-favorite').forEach(function(btn) {
                btn.addEventListener('click', function(e) {
                    e.preventDefault();
                    e.stopPropagation();
                    var trainerId = this.getAttribute('data-trainer-id');
                    PTPFavorite.toggle(this, trainerId);
                });
            });
        }
    };
    window.PTPRating = {
        init: function() {
            document.querySelectorAll('.ptp-rating-input').forEach(function(container) {
                var buttons = container.querySelectorAll('button');
                var input = container.querySelector('input[type="hidden"]');
                buttons.forEach(function(btn, index) {
                    btn.addEventListener('click', function() {
                        var rating = index + 1;
                        if (input) input.value = rating;
                        buttons.forEach(function(b, i) {
                            b.classList.toggle('active', i <= index);
                        });
                    });
                    btn.addEventListener('mouseenter', function() {
                        buttons.forEach(function(b, i) {
                            b.querySelector('svg').style.fill = i <= index ? 'var(--ptp-gold)' : 'var(--ptp-gray-200)';
                        });
                    });
                    btn.addEventListener('mouseleave', function() {
                        var currentRating = input ? parseInt(input.value) || 0 : 0;
                        buttons.forEach(function(b, i) {
                            b.querySelector('svg').style.fill = i < currentRating ? 'var(--ptp-gold)' : 'var(--ptp-gray-200)';
                        });
                    });
                });
            });
        }
    };
    window.PTPForm = {
        validate: function(form) {
            form = typeof form === 'string' ? document.querySelector(form) : form;
            if (!form) return false;
            var isValid = true;
            form.querySelectorAll('.ptp-input-error').forEach(function(el) {
                el.classList.remove('ptp-input-error');
            });
            form.querySelectorAll('.ptp-error-text').forEach(function(el) {
                el.remove();
            });
            form.querySelectorAll('[required]').forEach(function(input) {
                if (!input.value.trim()) {
                    isValid = false;
                    PTPForm.showError(input, 'This field is required');
                }
            });
            form.querySelectorAll('input[type="email"]').forEach(function(input) {
                if (input.value && !PTPForm.isValidEmail(input.value)) {
                    isValid = false;
                    PTPForm.showError(input, 'Please enter a valid email');
                }
            });
            return isValid;
        },
        showError: function(input, message) {
            input.classList.add('ptp-input-error');
            var error = document.createElement('div');
            error.className = 'ptp-error-text';
            error.textContent = message;
            input.parentNode.appendChild(error);
        },
        isValidEmail: function(email) {
            return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
        },
        init: function() {
            document.querySelectorAll('form[data-validate]').forEach(function(form) {
                form.addEventListener('submit', function(e) {
                    if (!PTPForm.validate(form)) {
                        e.preventDefault();
                        PTPToast.error('Please fix the errors above');
                    }
                });
            });
        }
    };
    window.PTPAnimate = {
        init: function() {
            if (!('IntersectionObserver' in window)) return;
            var observer = new IntersectionObserver(function(entries) {
                entries.forEach(function(entry) {
                    if (entry.isIntersecting) {
                        entry.target.classList.add('ptp-animated');
                        observer.unobserve(entry.target);
                    }
                });
            }, { threshold: 0.1 });
            document.querySelectorAll('[data-animate]').forEach(function(el) {
                observer.observe(el);
            });
        }
    };
    function init() {
        PTPModal.init();
        PTPBottomSheet.init();
        PTPTabs.init();
        PTPDropdown.init();
        PTPCopy.init();
        PTPScroll.init();
        PTPFavorite.init();
        PTPRating.init();
        PTPForm.init();
        PTPAnimate.init();
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();
(function() {
    'use strict';
    var isDesktop = window.innerWidth >= 1025;
    if (isDesktop) {
        document.documentElement.style.cssText += 'overflow-y: scroll !important; overflow-x: hidden !important; height: auto !important; position: static !important;';
        if (document.body) {
            document.body.style.cssText += 'overflow-y: auto !important; overflow-x: hidden !important; height: auto !important; position: static !important;';
        }
    }
    var blockingClasses = [
        'no-scroll',
        'modal-open',
        'overflow-hidden',
        'menu-open',
        'ptp-modal-open',
        'fixed-body',
        'body-fixed',
        'scroll-lock',
        'scroll-locked',
        'noscroll',
        'ast-main-header-nav-open',
        'ast-mobile-popup-open',
        'ast-header-break-point-active',
        'flavor-menu-open',
        'flavor-nav-open',
        'flavor-modal-open'
    ];
    function fixScrollBehavior() {
        var html = document.documentElement;
        html.style.setProperty('scroll-behavior', 'auto', 'important');
        if (document.body) {
            document.body.style.setProperty('scroll-behavior', 'auto', 'important');
        }
    }
    function safeScrollTo(x, y) {
        document.documentElement.scrollTop = y;
        document.body.scrollTop = y; // For Safari
        try {
            window.scrollTo({ top: y, left: x, behavior: 'instant' });
        } catch(e) {
            window.scrollTo(x, y);
        }
    }
    function forceScroll() {
        var html = document.documentElement;
        var body = document.body;
        fixScrollBehavior();
        blockingClasses.forEach(function(cls) {
            html.classList.remove(cls);
            body.classList.remove(cls);
        });
        if (window.innerWidth >= 1025) {
            var mobileMenuVisible = document.querySelector('.ptp-mobile-nav.open, .ptp-mobile-menu.open, .ast-mobile-popup-drawer.active');
            if (!mobileMenuVisible) {
                body.classList.remove('menu-open');
                body.classList.remove('ast-main-header-nav-open');
                body.classList.remove('ast-mobile-popup-open');
            }
        }
        html.style.setProperty('overflow-y', 'scroll', 'important');
        html.style.setProperty('overflow-x', 'hidden', 'important');
        html.style.setProperty('height', 'auto', 'important');
        html.style.setProperty('position', 'static', 'important');
        html.style.setProperty('scroll-behavior', 'auto', 'important');
        body.style.setProperty('overflow-y', 'auto', 'important');
        body.style.setProperty('overflow-x', 'hidden', 'important');
        body.style.setProperty('overflow', 'visible', 'important'); // Reset shorthand too
        body.style.setProperty('height', 'auto', 'important');
        body.style.setProperty('position', 'static', 'important');
        body.style.setProperty('top', 'auto', 'important');
        body.style.setProperty('left', 'auto', 'important');
        body.style.setProperty('right', 'auto', 'important');
        body.style.setProperty('width', '100%', 'important');
        body.style.setProperty('scroll-behavior', 'auto', 'important');
        var page = document.getElementById('page');
        if (page) {
            page.style.setProperty('overflow', 'visible', 'important');
            page.style.setProperty('height', 'auto', 'important');
            page.style.setProperty('position', 'static', 'important');
        }
        var siteContent = document.querySelector('.site-content');
        if (siteContent) {
            siteContent.style.setProperty('overflow', 'visible', 'important');
        }
        var astContainers = document.querySelectorAll('.ast-container, .ast-separate-container');
        astContainers.forEach(function(el) {
            el.style.setProperty('overflow', 'visible', 'important');
        });
        var flavorWrappers = document.querySelectorAll('.flavor-wrapper, #flavor-wrapper, .flavor-content');
        flavorWrappers.forEach(function(el) {
            el.style.setProperty('overflow', 'visible', 'important');
            el.style.setProperty('overflow-y', 'visible', 'important');
            el.style.setProperty('height', 'auto', 'important');
            el.style.setProperty('max-height', 'none', 'important');
            el.style.setProperty('min-height', '100vh', 'important');
            el.style.setProperty('position', 'relative', 'important');
            el.style.setProperty('transform', 'none', 'important');
        });
        if (window.innerWidth >= 1025) {
            var bodyChildren = body.children;
            for (var i = 0; i < bodyChildren.length; i++) {
                var child = bodyChildren[i];
                if (child.tagName !== 'SCRIPT' && child.tagName !== 'STYLE') {
                    var computed = window.getComputedStyle(child);
                    if ((computed.height === window.innerHeight + 'px' || computed.minHeight === '100vh') &&
                        (computed.overflow === 'hidden' || computed.overflowY === 'hidden')) {
                        child.style.setProperty('overflow', 'visible', 'important');
                        child.style.setProperty('overflow-y', 'visible', 'important');
                        child.style.setProperty('height', 'auto', 'important');
                        console.log('[PTP] Fixed scroll-blocking wrapper:', child.className || child.id);
                    }
                }
            }
        }
    }
    fixScrollBehavior();
    forceScroll();
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function() {
            fixScrollBehavior();
            forceScroll();
        });
    }
    window.addEventListener('load', function() {
        fixScrollBehavior();
        forceScroll();
        setTimeout(forceScroll, 100);
        setTimeout(forceScroll, 300);
        setTimeout(forceScroll, 500);
        setTimeout(forceScroll, 1000);
    });
    var checks = 0;
    var interval = setInterval(function() {
        fixScrollBehavior();
        forceScroll();
        checks++;
        if (checks >= 10) {
            clearInterval(interval);
        }
    }, 500);
    if (window.innerWidth >= 1025) {
        var desktopChecks = 0;
        var desktopInterval = setInterval(function() {
            var computed = window.getComputedStyle(document.body);
            var hasOpenModal = document.querySelector('.ptp-modal-overlay.open, .ptp-bottom-sheet-overlay.open, .modal.show, .ptp-mini-cart.active, [class*="modal"].open');
            var hasOpenMenu = document.body.classList.contains('menu-open') ||
                             document.body.classList.contains('ast-main-header-nav-open');
            if ((computed.overflowY === 'hidden' || computed.overflow === 'hidden') && !hasOpenModal && !hasOpenMenu) {
                console.log('[PTP] Desktop scroll still blocked - forcing');
                forceScroll();
            }
            document.body.style.setProperty('overflow-y', 'auto', 'important');
            document.documentElement.style.setProperty('overflow-y', 'scroll', 'important');
            desktopChecks++;
            if (desktopChecks >= 15) {
                clearInterval(desktopInterval);
            }
        }, 2000);
        setInterval(function() {
            if (window.innerWidth >= 1025) {
                var hasOpenModal = document.querySelector('.ptp-modal-overlay.open, .ptp-bottom-sheet-overlay.open, .modal.show, .ptp-mini-cart.active');
                if (!hasOpenModal) {
                    document.body.style.setProperty('overflow-y', 'auto', 'important');
                    document.documentElement.style.setProperty('overflow-y', 'scroll', 'important');
                }
            }
        }, 5000);
        window.addEventListener('resize', function() {
            if (window.innerWidth >= 1025) {
                setTimeout(forceScroll, 100);
            }
        });
    }
    if (typeof MutationObserver !== 'undefined') {
        var observer = new MutationObserver(function(mutations) {
            mutations.forEach(function(mutation) {
                if (mutation.attributeName === 'style' || mutation.attributeName === 'class') {
                    var target = mutation.target;
                    var computedStyle = window.getComputedStyle(document.documentElement);
                    if (computedStyle.scrollBehavior === 'smooth') {
                        fixScrollBehavior();
                    }
                    if (target === document.body || target === document.documentElement) {
                        var style = target.style;
                        var computed = window.getComputedStyle(target);
                        if (computed.overflowY === 'hidden' || style.overflow === 'hidden' || style.overflowY === 'hidden') {
                            var hasOpenModal = document.querySelector('.ptp-modal-overlay.open, .ptp-bottom-sheet-overlay.open, .modal.show, .ptp-mini-cart.active, [class*="modal"].open');
                            var hasOpenMenu = document.body.classList.contains('menu-open') ||
                                             document.body.classList.contains('ast-main-header-nav-open') ||
                                             document.body.classList.contains('ast-mobile-popup-open');
                            if (!hasOpenModal && !hasOpenMenu) {
                                console.log('[PTP] Scroll blocked without open modal - forcing scroll back');
                                forceScroll();
                            }
                        }
                    }
                }
            });
        });
        observer.observe(document.documentElement, { attributes: true, attributeFilter: ['style', 'class'] });
        if (document.body) {
            observer.observe(document.body, { attributes: true, attributeFilter: ['style', 'class'] });
        }
    }
    var originalScrollTo = window.scrollTo;
    window.scrollTo = function(x, y) {
        if (typeof x === 'object') {
            x.behavior = 'instant';
            return originalScrollTo.call(window, x);
        } else {
            return originalScrollTo.call(window, { top: y, left: x, behavior: 'instant' });
        }
    };
    window.scroll = window.scrollTo;
    var originalScrollBy = window.scrollBy;
    window.scrollBy = function(x, y) {
        if (typeof x === 'object') {
            x.behavior = 'instant';
            return originalScrollBy.call(window, x);
        } else {
            return originalScrollBy.call(window, { top: y, left: x, behavior: 'instant' });
        }
    };
    window.ptpForceScroll = forceScroll;
    window.ptpSafeScrollTo = safeScrollTo;
    window.ptpFixScrollBehavior = fixScrollBehavior;
    window.ptpScrollDiag = function() {
        console.log('=== PTP SCROLL DIAGNOSTIC ===');
        console.log('Window width:', window.innerWidth);
        console.log('Is desktop:', window.innerWidth >= 1025);
        var html = document.documentElement;
        var body = document.body;
        console.log('\n--- HTML Element ---');
        console.log('Classes:', html.className);
        console.log('Style overflow:', html.style.overflow);
        console.log('Style overflow-y:', html.style.overflowY);
        console.log('Computed overflow:', window.getComputedStyle(html).overflow);
        console.log('Computed overflow-y:', window.getComputedStyle(html).overflowY);
        console.log('\n--- BODY Element ---');
        console.log('Classes:', body.className);
        console.log('Style overflow:', body.style.overflow);
        console.log('Style overflow-y:', body.style.overflowY);
        console.log('Computed overflow:', window.getComputedStyle(body).overflow);
        console.log('Computed overflow-y:', window.getComputedStyle(body).overflowY);
        console.log('Computed height:', window.getComputedStyle(body).height);
        console.log('Computed position:', window.getComputedStyle(body).position);
        console.log('\n--- Potential Blockers ---');
        var blockers = [];
        var allElements = document.querySelectorAll('body > *:not(script):not(style)');
        allElements.forEach(function(el) {
            var computed = window.getComputedStyle(el);
            if (computed.overflow === 'hidden' || computed.overflowY === 'hidden') {
                blockers.push({
                    element: el,
                    tag: el.tagName,
                    id: el.id,
                    class: el.className,
                    overflow: computed.overflow,
                    overflowY: computed.overflowY,
                    height: computed.height
                });
            }
        });
        if (blockers.length) {
            console.log('Found potential scroll blockers:');
            blockers.forEach(function(b) {
                console.log('  -', b.tag, b.id || b.class, '| overflow:', b.overflow, '| height:', b.height);
            });
        } else {
            console.log('No obvious blockers found in direct body children');
        }
        console.log('\n--- Document Scroll Info ---');
        console.log('documentElement.scrollHeight:', html.scrollHeight);
        console.log('body.scrollHeight:', body.scrollHeight);
        console.log('window.innerHeight:', window.innerHeight);
        console.log('Can scroll:', html.scrollHeight > window.innerHeight);
        console.log('\n--- Fix Status ---');
        console.log('To force scroll: ptpForceScroll()');
        console.log('=============================');
    };
    console.log('[PTP] Scroll fix v135.2 loaded - scroll-behavior: smooth disabled, desktop scroll enforced');
})();